<?phpif (!defined('OK_LOADED')) exit;// ---------------------------------------------------------------------// CONFIG: სესიის სინქრონიზაცია// ---------------------------------------------------------------------if (session_status() === PHP_SESSION_NONE) {    session_start();}if (!defined('OK_USER_SESSION_KEY')) {    define('OK_USER_SESSION_KEY', 'user_id'); }// ---------------------------------------------------------------------// 0. სისტემური ფიქსები (Shortcode Functions)// ---------------------------------------------------------------------if (!function_exists('add_ok_shortcode')) {    function add_ok_shortcode($tag, $func) {        if (function_exists('add_shortcode')) {            add_shortcode($tag, $func);        } else {            global $ok_shortcodes;            $ok_shortcodes[$tag] = $func;        }    }}if (!function_exists('do_ok_shortcode')) {    function do_ok_shortcode($content) {        if (function_exists('ok_do_shortcode')) return ok_do_shortcode($content);        if (function_exists('do_shortcode')) return do_shortcode($content);        return $content;    }}// ---------------------------------------------------------------------// 1. დამხმარე ფუნქციები// ---------------------------------------------------------------------if (!function_exists('ok_get_current_user_id')) {    function ok_get_current_user_id() {        return isset($_SESSION[OK_USER_SESSION_KEY]) ? (int)$_SESSION[OK_USER_SESSION_KEY] : 0;    }}if (!function_exists('ok_show_flash_msg')) {    function ok_show_flash_msg() {        if (isset($_SESSION['ok_app_flash_msg'])) {            $msg = $_SESSION['ok_app_flash_msg'];            echo '<div class="alert alert-'.$msg['type'].' alert-dismissible fade show" role="alert">                    '.$msg['text'].'                    <button type="button" class="btn-close" data-bs-dismiss="alert" aria-label="Close"></button>                  </div>';            unset($_SESSION['ok_app_flash_msg']);        }    }}// ---------------------------------------------------------------------// 2. მომხმარებლის კაბინეტი: [ok_user_cabinet]// ---------------------------------------------------------------------add_ok_shortcode('ok_user_cabinet', function() {    global $ok_db;    $user_id = ok_get_current_user_id();        ob_start();        echo '<link rel="stylesheet" href="https://cdn.jsdelivr.net/npm/bootstrap-icons@1.11.3/font/bootstrap-icons.min.css">';        // A. თუ არ არის ავტორიზებული -> მხოლოდ შეტყობინება    if ($user_id <= 0) {        ok_show_flash_msg();        echo '<div class="alert alert-warning">კაბინეტის სანახავად გთხოვთ გაიაროთ ავტორიზაცია.</div>';        return ob_get_clean();    }    // B. მონაცემების მომზადება    $display_name = isset($_SESSION['display_name']) ? $_SESSION['display_name'] : 'მომხმარებელო';    if ($display_name === 'მომხმარებელო' && isset($ok_db)) {         $curr_user = $ok_db->get_row("SELECT display_name FROM ok_users WHERE id = '$user_id'");         if ($curr_user) $display_name = $curr_user->display_name;    }    $my_apps = [];    if(isset($ok_db)) {        $my_apps = $ok_db->get_results("            SELECT a.*, s.title as s_name, u.display_name as p_name             FROM ok_appointments a             JOIN ok_services s ON a.service_id = s.id             JOIN ok_users u ON a.provider_id = u.id             WHERE a.customer_id = '$user_id'            ORDER BY a.appointment_date DESC, a.appointment_time DESC        ");    }    ok_show_flash_msg();    // C. თემფლეითის ჩატვირთვა    $template_file = __DIR__ . '/../templates/user-cabinet-ui.php';    if (file_exists($template_file)) {        include $template_file;    } else {        echo '<div class="alert alert-danger">                შეცდომა: თემფლეითი ვერ მოიძებნა: <b>templates/user-cabinet-ui.php</b>              </div>';    }    return ob_get_clean();});// ---------------------------------------------------------------------// 3. პროვაიდერის კაბინეტი: [ok_provider_cabinet]// ---------------------------------------------------------------------add_ok_shortcode('ok_provider_cabinet', function() {    global $ok_db;    $user_id = ok_get_current_user_id();        ob_start();    echo '<link rel="stylesheet" href="https://cdn.jsdelivr.net/npm/bootstrap-icons@1.11.3/font/bootstrap-icons.min.css">';        // A. თუ არ არის ავტორიზებული -> გადამისამართება ლოგინზე    if ($user_id <= 0) {        echo '<script>window.location.href = "/login";</script>';        return ob_get_clean();    }    // B. მონაცემების მომზადება    $incoming_apps = [];    if(isset($ok_db)) {        $incoming_apps = $ok_db->get_results("            SELECT a.*, s.title as s_name, u.display_name as c_name, u.email as c_email             FROM ok_appointments a             JOIN ok_services s ON a.service_id = s.id             JOIN ok_users u ON a.customer_id = u.id             WHERE a.provider_id = '$user_id'            ORDER BY a.appointment_date DESC, a.appointment_time DESC        ");    }    ok_show_flash_msg();    // C. თემფლეითის ჩატვირთვა    $template_file = __DIR__ . '/../templates/provider-cabinet-ui.php';    if (file_exists($template_file)) {        include $template_file;    } else {        echo '<div class="alert alert-danger">                შეცდომა: თემფლეითი ვერ მოიძებნა: <b>templates/provider-cabinet-ui.php</b>              </div>';    }    return ob_get_clean();});// ---------------------------------------------------------------------// 4. მთავარი როუტერი: [ok_main_cabinet]// ---------------------------------------------------------------------add_ok_shortcode('ok_main_cabinet', function() {    global $ok_db;    $user_id = ok_get_current_user_id();    // თუ არ არის შესული, ვაჩვენებთ იუზერის ნაწილს (სადაც შეტყობინება დახვდება)    if ($user_id === 0) {        return do_ok_shortcode('[ok_user_cabinet]');    }    // ვამოწმებთ არის თუ არა პროვაიდერი    $is_provider = null;    if(isset($ok_db)) {        $is_provider = $ok_db->get_var("SELECT id FROM ok_providers WHERE user_id = '$user_id' LIMIT 1");    }        if ($is_provider) {        return do_ok_shortcode('[ok_provider_cabinet]');    } else {        return do_ok_shortcode('[ok_user_cabinet]');    }});// ---------------------------------------------------------------------// 5. ჯავშნის ფორმა: [ok_booking_form]// ---------------------------------------------------------------------add_ok_shortcode('ok_booking_form', function() {    global $ok_db;    ob_start();        echo '<script src="https://cdn.jsdelivr.net/npm/sweetalert2@11"></script>';    $user_id = ok_get_current_user_id();    // თუ არ არის ავტორიზებული -> მხოლოდ შეტყობინება    if ($user_id === 0) {        ok_show_flash_msg();        echo '<div class="alert alert-info">ჯავშნის გასაკეთებლად საჭიროა ავტორიზაცია.</div>';        return ob_get_clean();    }    $providers = [];    if(isset($ok_db)) {        $providers = $ok_db->get_results("SELECT p.user_id, u.display_name FROM ok_providers p JOIN ok_users u ON p.user_id = u.id");    }    ?>    <div class="ok-booking-wrapper p-4 border rounded bg-white shadow-sm mt-3 mx-auto" style="max-width:600px;">        <h4 class="mb-4 text-center fw-bold text-primary">ვიზიტის დაჯავშნა</h4>                <form id="ok_booking_form_el">            <div class="mb-3">                <label class="form-label fw-bold small text-uppercase text-muted">1. აირჩიეთ სპეციალისტი</label>                <select name="provider_id" id="ok_provider" class="form-select form-select-lg" required>                    <option value="">-- აირჩიეთ --</option>                    <?php foreach($providers as $p): ?>                        <option value="<?php echo $p->user_id; ?>"><?php echo $p->display_name; ?></option>                    <?php endforeach; ?>                </select>            </div>            <div class="mb-3">                <label class="form-label fw-bold small text-uppercase text-muted">2. აირჩიეთ სერვისი</label>                <select name="service_id" id="ok_service" class="form-select form-select-lg" disabled required>                    <option value="">ჯერ აირჩიეთ სპეციალისტი</option>                </select>            </div>            <div class="mb-3">                <label class="form-label fw-bold small text-uppercase text-muted">3. აირჩიეთ თარიღი</label>                <input type="date" name="date" id="ok_date" class="form-control form-control-lg" disabled required min="<?php echo date('Y-m-d'); ?>">            </div>            <div class="mb-3">                <label class="form-label fw-bold small text-uppercase text-muted">4. აირჩიეთ დრო</label>                <select name="time" id="ok_time" class="form-select form-select-lg" disabled required>                    <option value="">ჯერ აირჩიეთ თარიღი</option>                </select>                <div id="ok_loader" class="text-primary mt-2 small" style="display:none;">                    <span class="spinner-border spinner-border-sm"></span> მონაცემები იტვირთება...                </div>            </div>            <button type="submit" id="ok_btn" class="btn btn-primary w-100 btn-lg mt-3" disabled>                <i class="bi bi-calendar-plus me-2"></i>დაჯავშნა            </button>        </form>    </div>    <script>    window.ok_initiate_payment = function(appId, methodKey) {        Swal.fire({            title: 'კავშირი ბანკთან...',            didOpen: () => Swal.showLoading()        });        let fd = new FormData();        fd.append('ok_action', 'select_payment_method');        fd.append('appointment_id', appId);        fd.append('method', methodKey);        fetch(window.location.href, { method: 'POST', body: fd })            .then(r => r.json())            .then(res => {                if (res.success && res.redirect_url) {                    window.location.href = res.redirect_url;                } else {                    Swal.fire('შეცდომა', res.message || 'ვერ მოხერხდა გადამისამართება', 'error');                }            })            .catch(() => Swal.fire('შეცდომა', 'კავშირის პრობლემა', 'error'));    };    document.addEventListener('DOMContentLoaded', function() {        const provider = document.getElementById('ok_provider');        const service = document.getElementById('ok_service');        const date = document.getElementById('ok_date');        const time = document.getElementById('ok_time');        const btn = document.getElementById('ok_btn');        const loader = document.getElementById('ok_loader');        async function okFetch(action, params = {}) {            loader.style.display = 'block';            const fd = new FormData();            fd.append('ok_action', action);            for(let k in params) fd.append(k, params[k]);            try {                const req = await fetch(window.location.href, {method:'POST', body:fd});                return await req.json();            } catch(e) { console.error(e); return {success:false}; }            finally { loader.style.display = 'none'; }        }        provider.addEventListener('change', async function() {            service.innerHTML = '<option>იტვირთება...</option>';            service.disabled = true; date.disabled = true; time.disabled = true; btn.disabled = true;            date.value = ''; time.innerHTML = '<option>ჯერ აირჩიეთ თარიღი</option>';            if(!this.value) return;            const res = await okFetch('get_services', {provider_id: this.value});                        service.innerHTML = '<option value="">-- აირჩიეთ სერვისი --</option>';            if(res.success && res.services) {                res.services.forEach(s => {                    service.innerHTML += `<option value="${s.id}">${s.title} (${s.price} GEL)</option>`;                });                service.disabled = false;            }        });        service.addEventListener('change', function() {            date.disabled = !this.value;            date.value = ''; time.disabled = true; btn.disabled = true;        });        date.addEventListener('change', async function() {            time.innerHTML = '<option>მოწმდება...</option>';            time.disabled = true; btn.disabled = true;            if(!this.value) return;            const res = await okFetch('get_slots', {                service_id: service.value,                date: this.value            });            if(res.success && res.slots.length > 0) {                time.innerHTML = '<option value="">-- აირჩიეთ დრო --</option>';                res.slots.forEach(t => {                    time.innerHTML += `<option value="${t}">${t}</option>`;                });                time.disabled = false;            } else {                time.innerHTML = '<option>ადგილები არ არის</option>';            }        });        time.addEventListener('change', function() {            btn.disabled = !this.value;        });        document.getElementById('ok_booking_form_el').addEventListener('submit', async function(e) {            e.preventDefault();            btn.disabled = true;                        const fd = new FormData(this);            fd.append('ok_action', 'submit_booking');                        loader.style.display = 'block';            const req = await fetch(window.location.href, {method:'POST', body:fd});            const res = await req.json();            loader.style.display = 'none';            if(res.success) {                if(res.payment_required) {                    let html = '<div class="d-flex justify-content-center gap-3 mt-3">';                    if(res.payment_methods) {                        res.payment_methods.forEach(m => {                            html += `<div onclick="ok_initiate_payment(${res.appointment_id}, '${m.id}')"                                             style="cursor:pointer; border:1px solid #ddd; padding:10px; border-radius:8px;">                                            <img src="${m.logo}" style="height:40px;">                                            <div class="small fw-bold mt-1">${m.title}</div>                                     </div>`;                        });                    }                    html += '</div>';                                        Swal.fire({                        title: 'გადახდის მეთოდი',                        html: res.message + html,                        showConfirmButton: false,                        showCloseButton: true                    });                } else {                    Swal.fire('წარმატება!', res.message, 'success').then(() => {                        window.location.href = '?ok_page=cabinet';                    });                }            } else {                Swal.fire('შეცდომა', res.message, 'error');                btn.disabled = false;            }        });    });    </script>    <?php    return ob_get_clean();});?>